INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000690', 'Wireline logging adalah kegiatan merekam...', 'Wireline logging is the activity of recording...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:50:"Sifat fisik batuan terhadap kedalaman lubang sumur";i:1;s:24:"Volume lumpur pengeboran";i:2;s:19:"Harga minyak harian";i:3;s:21:"Jumlah pekerja di rig";}', 'a:4:{i:0;s:46:"Rock physical properties versus borehole depth";i:1;s:19:"Drilling mud volume";i:2;s:16:"Daily oil prices";i:3;s:32:"The number of workers on the rig";}', '', 'Sifat fisik batuan terhadap kedalaman lubang sumur', 'Rock physical properties versus borehole depth', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000691', 'Log gamma ray umumnya digunakan untuk...', 'The gamma ray log is generally used to...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:24:"Mengukur densitas fluida";i:1;s:62:"Mengukur radioaktivitas alami batuan sebagai indikator lempung";i:2;s:24:"Mengukur porositas total";i:3;s:28:"Mengukur resistivitas fluida";}', 'a:4:{i:0;s:21:"Measure fluid density";i:1;s:65:"Measure the natural radioactivity of the rock as a clay indicator";i:2;s:22:"Measure total porosity";i:3;s:25:"Measure fluid resistivity";}', '', 'Mengukur radioaktivitas alami batuan sebagai indikator lempung', 'Measure the natural radioactivity of the rock as a clay indicator', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000692', 'Log resistivitas digunakan untuk membedakan...', 'The resistivity log is used to distinguish...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:30:"Sumur vertikal dari horizontal";i:1;s:49:"Zona berisi hidrokarbon dari zona berisi air asin";i:2;s:17:"Core dari cutting";i:3;s:26:"Batupasir dari batugamping";}', 'a:4:{i:0;s:36:"Vertical wells from horizontal wells";i:1;s:50:"Hydrocarbon-bearing zones from brine-bearing zones";i:2;s:18:"Core from cuttings";i:3;s:24:"Sandstone from limestone";}', '', 'Zona berisi hidrokarbon dari zona berisi air asin', 'Hydrocarbon-bearing zones from brine-bearing zones', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000693', 'Density log (RHOB) mengukur...', 'The density log (RHOB) measures...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:22:"Kecepatan suara batuan";i:1;s:21:"Densitas bulk formasi";i:2;s:30:"Densitas fluida reservoir saja";i:3;s:20:"Resistivitas formasi";}', 'a:4:{i:0;s:22:"Rock acoustic velocity";i:1;s:22:"Formation bulk density";i:2;s:28:"Reservoir fluid density only";i:3;s:21:"Formation resistivity";}', '', 'Densitas bulk formasi', 'Formation bulk density', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000694', 'Neutron log terutama digunakan untuk mengukur...', 'The neutron log is primarily used to measure...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:12:"Kadar sulfur";i:1;s:36:"Porositas melalui kandungan hidrogen";i:2;s:15:"Kedalaman sumur";i:3;s:17:"Tekanan reservoir";}', 'a:4:{i:0;s:14:"Sulfur content";i:1;s:33:"Porosity through hydrogen content";i:2;s:10:"Well depth";i:3;s:18:"Reservoir pressure";}', '', 'Porositas melalui kandungan hidrogen', 'Porosity through hydrogen content', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000695', 'Sonic log mengukur...', 'The sonic log measures...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:21:"Radioaktivitas batuan";i:1;s:15:"Densitas fluida";i:2;s:43:"Waktu tempuh gelombang akustik dalam batuan";i:3;s:19:"Resistivitas batuan";}', 'a:4:{i:0;s:18:"Rock radioactivity";i:1;s:13:"Fluid density";i:2;s:45:"The travel time of acoustic waves in the rock";i:3;s:16:"Rock resistivity";}', '', 'Waktu tempuh gelombang akustik dalam batuan', 'The travel time of acoustic waves in the rock', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000696', 'Log SP (spontaneous potential) paling berguna untuk...', 'The SP (spontaneous potential) log is most useful for...', 'option', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:25:"Menentukan kekuatan semen";i:1;s:25:"Mengukur densitas matriks";i:2;s:46:"Mendeteksi lapisan permeabel dan menentukan Rw";i:3;s:42:"Mengukur porositas efektif secara langsung";}', 'a:4:{i:0;s:27:"Determining cement strength";i:1;s:24:"Measuring matrix density";i:2;s:43:"Detecting permeable beds and determining Rw";i:3;s:37:"Directly measuring effective porosity";}', '', 'Mendeteksi lapisan permeabel dan menentukan Rw', 'Detecting permeable beds and determining Rw', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000697', 'Log apa saja yang umum dipakai untuk estimasi porositas?', 'Which logs are commonly used to estimate porosity?', 'multi', 'PFC000000004', 'Inisialisasi', 'a:4:{i:0;s:9:"Sonic log";i:1;s:11:"Neutron log";i:2;s:13:"Gamma ray log";i:3;s:11:"Density log";}', 'a:4:{i:0;s:9:"Sonic log";i:1;s:11:"Neutron log";i:2;s:13:"Gamma ray log";i:3;s:11:"Density log";}', '', 'a:3:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:9:"Sonic log";}', 'a:3:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:9:"Sonic log";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000698', 'Urutkan nilai resistivitas formasi dari yang paling rendah ke paling tinggi.', 'Arrange formation resistivity values from lowest to highest.', 'drag', 'PFC000000004', 'Inisialisasi', 'a:5:{i:0;s:23:"Formasi batubara (coal)";i:1;s:16:"Air asin (brine)";i:2;s:9:"Air tawar";i:3;s:6:"Minyak";i:4;s:3:"Gas";}', 'a:5:{i:0;s:14:"Coal formation";i:1;s:5:"Brine";i:2;s:11:"Fresh water";i:3;s:3:"Oil";i:4;s:3:"Gas";}', '', 'a:4:{i:0;s:16:"Air asin (brine)";i:1;s:9:"Air tawar";i:2;s:6:"Minyak";i:3;s:3:"Gas";}', 'a:4:{i:0;s:5:"Brine";i:1;s:11:"Fresh water";i:2;s:3:"Oil";i:3;s:3:"Gas";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000699', 'Benarkah nilai gamma ray yang tinggi menandakan zona reservoir yang bersih?', 'Is it true that a high gamma ray value indicates a clean reservoir zone?', 'yesorno', 'PFC000000004', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000700', 'Diketahui RHOB 2,20 g/cc, densitas matriks 2,65 g/cc, densitas fluida 1,00 g/cc. Berapa porositas densitas (phi D)?', 'Given RHOB 2.20 g/cc, matrix density 2.65 g/cc, and fluid density 1.00 g/cc. What is the density porosity (phi D)?', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:5:"45,0%";i:1;s:5:"18,2%";i:2;s:5:"33,3%";i:3;s:5:"27,3%";}', 'a:4:{i:0;s:5:"45.0%";i:1;s:5:"18.2%";i:2;s:5:"33.3%";i:3;s:5:"27.3%";}', '', '27,3%', '27.3%', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000701', 'Efek crossover antara kurva neutron dan density yang saling menjauh biasanya menandakan...', 'The crossover effect between diverging neutron and density curves usually indicates...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:15:"Adanya air asin";i:1;s:20:"Kerusakan lubang bor";i:2;s:23:"Adanya gas (gas effect)";i:3;s:13:"Batuan serpih";}', 'a:4:{i:0;s:21:"The presence of brine";i:1;s:15:"Borehole damage";i:2;s:32:"The presence of gas (gas effect)";i:3;s:10:"Shale rock";}', '', 'Adanya gas (gas effect)', 'The presence of gas (gas effect)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000702', 'Indeks gamma ray (IGR) dihitung dengan persamaan...', 'The gamma ray index (IGR) is calculated by the equation...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:20:"(GRmin + GR) / GRmax";i:1;s:17:"(GRmax - GR) / GR";i:2;s:30:"(GR - GRmin) / (GRmax - GRmin)";i:3;s:16:"GR / GRmax x 100";}', 'a:4:{i:0;s:20:"(GRmin + GR) / GRmax";i:1;s:17:"(GRmax - GR) / GR";i:2;s:30:"(GR - GRmin) / (GRmax - GRmin)";i:3;s:16:"GR / GRmax x 100";}', '', '(GR - GRmin) / (GRmax - GRmin)', '(GR - GRmin) / (GRmax - GRmin)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000703', 'Log induksi (induction log) paling tepat digunakan pada...', 'The induction log is most appropriate for use in...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:26:"Lubang bor berisi air asin";i:1;s:59:"Lubang bor berisi lumpur berbasis minyak atau lubang kosong";i:2;s:22:"Sumur yang belum dibor";i:3;s:30:"Lubang bor yang sangat dangkal";}', 'a:4:{i:0;s:23:"Wells filled with brine";i:1;s:39:"Wells with oil-based mud or empty holes";i:2;s:30:"Wells that are not drilled yet";i:3;s:22:"Very shallow boreholes";}', '', 'Lubang bor berisi lumpur berbasis minyak atau lubang kosong', 'Wells with oil-based mud or empty holes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000704', 'Caliper log digunakan untuk...', 'The caliper log is used to...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:26:"Mengukur porositas efektif";i:1;s:51:"Mengukur diameter lubang bor dan mendeteksi washout";i:2;s:33:"Mengukur resistivitas air formasi";i:3;s:28:"Menentukan jenis hidrokarbon";}', 'a:4:{i:0;s:26:"Measure effective porosity";i:1;s:45:"Measure borehole diameter and detect washouts";i:2;s:35:"Measure formation water resistivity";i:3;s:30:"Determine the hydrocarbon type";}', '', 'Mengukur diameter lubang bor dan mendeteksi washout', 'Measure borehole diameter and detect washouts', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000705', 'Kurva SP yang terdefleksi ke kiri (negatif) relatif terhadap baseline serpih umumnya menandakan...', 'An SP curve deflected to the left (negative) relative to the shale baseline generally indicates...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:68:"Zona permeabel dengan salinitas air formasi lebih tinggi dari lumpur";i:1;s:38:"Zona dengan resistivitas sangat tinggi";i:2;s:17:"Zona tanpa fluida";i:3;s:17:"Zona serpih tebal";}', 'a:4:{i:0;s:66:"A permeable zone with formation water salinity higher than the mud";i:1;s:31:"A zone of very high resistivity";i:2;s:20:"A zone without fluid";i:3;s:18:"A thick shale zone";}', '', 'Zona permeabel dengan salinitas air formasi lebih tinggi dari lumpur', 'A permeable zone with formation water salinity higher than the mud', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000706', 'Micro-resistivity log (MSFL) digunakan untuk menentukan...', 'The micro-resistivity log (MSFL) is used to determine...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:16:"Densitas matriks";i:1;s:25:"Resistivitas batuan induk";i:2;s:21:"Kedalaman total sumur";i:3;s:31:"Resistivitas zona flushed (Rxo)";}', 'a:4:{i:0;s:14:"Matrix density";i:1;s:23:"Source rock resistivity";i:2;s:16:"Total well depth";i:3;s:30:"Flushed zone resistivity (Rxo)";}', '', 'Resistivitas zona flushed (Rxo)', 'Flushed zone resistivity (Rxo)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000707', 'Faktor fotolistrik (PEF) sangat berguna untuk...', 'The photoelectric factor (PEF) is very useful for...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:24:"Mengukur laju alir sumur";i:1;s:44:"Identifikasi litologi (jenis mineral batuan)";i:2;s:23:"Menentukan tekanan pori";i:3;s:28:"Menentukan viskositas minyak";}', 'a:4:{i:0;s:24:"Measuring well flow rate";i:1;s:44:"Lithology identification (rock mineral type)";i:2;s:25:"Determining pore pressure";i:3;s:25:"Determining oil viscosity";}', '', 'Identifikasi litologi (jenis mineral batuan)', 'Lithology identification (rock mineral type)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000708', 'Persamaan Wyllie time-average pada sonic log digunakan untuk...', 'The Wyllie time-average equation on the sonic log is used to...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:31:"Menghitung saturasi hidrokarbon";i:1;s:28:"Mengukur diameter lubang bor";i:2;s:27:"Menghitung resistivitas air";i:3;s:48:"Menghitung porositas dari waktu tempuh gelombang";}', 'a:4:{i:0;s:32:"Calculate hydrocarbon saturation";i:1;s:25:"Measure borehole diameter";i:2;s:27:"Calculate water resistivity";i:3;s:44:"Calculate porosity from acoustic travel time";}', '', 'Menghitung porositas dari waktu tempuh gelombang', 'Calculate porosity from acoustic travel time', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000709', 'NMR log memberikan informasi terutama mengenai...', 'The NMR log provides information primarily about...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:52:"Distribusi ukuran pori dan fluida bebas (free fluid)";i:1;s:15:"Kekuatan casing";i:2;s:15:"Kedalaman sumur";i:3;s:26:"Jenis mineral lempung saja";}', 'a:4:{i:0;s:37:"Pore size distribution and free fluid";i:1;s:15:"Casing strength";i:2;s:10:"Well depth";i:3;s:23:"Clay mineral types only";}', '', 'Distribusi ukuran pori dan fluida bebas (free fluid)', 'Pore size distribution and free fluid', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000710', 'Hukum Archie digunakan untuk menghitung...', 'Archie''s law is used to calculate...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:23:"Porositas dari densitas";i:1;s:38:"Saturasi air dari resistivitas formasi";i:2;s:31:"Permeabilitas dari ukuran butir";i:3;s:27:"Kedalaman dari waktu tempuh";}', 'a:4:{i:0;s:21:"Porosity from density";i:1;s:43:"Water saturation from formation resistivity";i:2;s:28:"Permeability from grain size";i:3;s:22:"Depth from travel time";}', '', 'Saturasi air dari resistivitas formasi', 'Water saturation from formation resistivity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000711', 'Resistivitas air formasi (Rw) dapat diturunkan dari...', 'Formation water resistivity (Rw) can be derived from...', 'option', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:11:"Log caliper";i:1;s:43:"Kurva SP atau pengukuran sampel air formasi";i:2;s:20:"Kurva gamma ray saja";i:3;s:14:"Kurva densitas";}', 'a:4:{i:0;s:15:"The caliper log";i:1;s:39:"The SP curve or formation water samples";i:2;s:25:"The gamma ray curve alone";i:3;s:17:"The density curve";}', '', 'Kurva SP atau pengukuran sampel air formasi', 'The SP curve or formation water samples', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000712', 'Manakah faktor yang memengaruhi kualitas pengukuran log?', 'Which factors affect log measurement quality?', 'multi', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:17:"Kecepatan logging";i:1;s:37:"Kondisi lubang bor (washout, mudcake)";i:2;s:29:"Jenis lumpur dan salinitasnya";i:3;s:25:"Warna batuan di permukaan";}', 'a:4:{i:0;s:13:"Logging speed";i:1;s:37:"Borehole condition (washout, mudcake)";i:2;s:21:"Mud type and salinity";i:3;s:25:"Rock color at the surface";}', '', 'a:3:{i:0;s:37:"Kondisi lubang bor (washout, mudcake)";i:1;s:29:"Jenis lumpur dan salinitasnya";i:2;s:17:"Kecepatan logging";}', 'a:3:{i:0;s:37:"Borehole condition (washout, mudcake)";i:1;s:21:"Mud type and salinity";i:2;s:13:"Logging speed";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
