INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000715', 'Manakah keterbatasan log resistivitas?', 'Which are limitations of the resistivity log?', 'multi', 'PFC000000004', 'Final Advanced', 'a:4:{i:0;s:25:"Dipengaruhi invasi lumpur";i:1;s:26:"Tidak dipengaruhi litologi";i:2;s:25:"Perlu nilai Rw yang andal";i:3;s:49:"Tidak dapat membaca formasi yang sangat konduktif";}', 'a:4:{i:0;s:24:"Affected by mud invasion";i:1;s:23:"Unaffected by lithology";i:2;s:20:"Requires reliable Rw";i:3;s:40:"Cannot read highly conductive formations";}', '', 'a:3:{i:0;s:49:"Tidak dapat membaca formasi yang sangat konduktif";i:1;s:25:"Dipengaruhi invasi lumpur";i:2;s:25:"Perlu nilai Rw yang andal";}', 'a:3:{i:0;s:40:"Cannot read highly conductive formations";i:1;s:24:"Affected by mud invasion";i:2;s:20:"Requires reliable Rw";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
